/**
 * Ownership handover offers. At most one offer per organization is open
 * (`pending` and unexpired); a lapsed offer is still `pending` until the next
 * offer flips it to `expired`, and nothing else ever reads it as open.
 *
 * Must call (do not reimplement): orgPredicate, toOwnershipHandover
 */
import { and, desc, eq, gt, lte, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

/** The most recent `pending` offer, lapsed or not; callers decide what it means. */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .limit(1)
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Opens a new offer unless one is already open at `now`. Lapsed offers are
 * marked `expired` in the same transaction so they stop reading as pending.
 * Returns `null` when an open offer already exists.
 */
export function insertOpenHandover(input: {
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly now: IsoTimestamp;
  readonly expiresAt: IsoTimestamp;
}): OwnershipHandover | null {
  return getDb().transaction((tx) => {
    tx.update(ownershipHandovers)
      .set({ status: "expired", resolvedAt: input.expiresAt, updatedAt: input.now })
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, input.orgId),
          eq(ownershipHandovers.status, "pending"),
          lte(ownershipHandovers.expiresAt, input.now),
        ),
      )
      .run();

    const open = tx
      .select({ id: ownershipHandovers.id })
      .from(ownershipHandovers)
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, input.orgId),
          eq(ownershipHandovers.status, "pending"),
          gt(ownershipHandovers.expiresAt, input.now),
        ),
      )
      .get();
    if (open) return null;

    const row = tx
      .insert(ownershipHandovers)
      .values({
        id: newId(),
        orgId: input.orgId,
        fromUserId: input.fromUserId,
        toUserId: input.toUserId,
        status: "pending",
        expiresAt: input.expiresAt,
        resolvedAt: null,
        createdAt: input.now,
        updatedAt: input.now,
      })
      .returning()
      .get();

    return toOwnershipHandover(row);
  });
}

/** Moves a pending offer to a terminal status and stamps when it was resolved. */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${handoverId} not found in org ${orgId}`);
  return toOwnershipHandover(row);
}

/**
 * Withdraws the open offers that a removed member is party to, so neither the
 * offered member nor the outgoing owner can act on them afterwards.
 */
export async function cancelOpenHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
