s=open(path).read()
s=s.rstrip('\n')+'''

/**
 * Offers the workspace to another active member. Only the recorded owner may
 * offer, and only one offer may be open at a time.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const offer = await ownershipHandoverRepo.insertOpenHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    now: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + OWNERSHIP_OFFER_TTL_MS)),
  });
  if (offer === null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership offered to you",
    body: `${actor.userId} offered you ownership of this workspace`,
    href: "/settings",
    actorId: actor.userId,
  });

  return offer;
}

/**
 * The offered member takes over. The acceptor is promoted to owner before the
 * previous owner is stepped down, so the workspace has an owner throughout.
 * Every role change and the transfer itself are published on behalf of the
 * acceptor.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const offer = await actionableOffer(actor, orgId, now);

  const acceptor = await memberRepo.findMember(orgId, actor.userId);
  if (!acceptor || acceptor.status !== "active") {
    throw new NotFoundError("Member", actor.userId);
  }
  const previous = await memberRepo.findMember(orgId, offer.fromUserId);

  if (acceptor.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, acceptor.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: acceptor.role,
      to: promoted.role,
    });
  }

  await orgRepo.setOrgOwner(orgId, actor.userId);

  if (previous && previous.role === "owner") {
    const demoted = await memberRepo.updateMemberRole(orgId, previous.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: "owner",
      to: demoted.role,
    });
  }

  await ownershipHandoverRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    toIsoTimestamp(now),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: offer.fromUserId,
    toUserId: actor.userId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/** The offered member turns the workspace down; the owner may offer again afterwards. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const offer = await actionableOffer(actor, orgId, now);

  return ownershipHandoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(now),
  );
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);

  const now = new Date();
  const offer = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (!offer || isLapsed(offer, now)) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return ownershipHandoverRepo.resolveHandover(
    orgId,
    offer.id,
    "canceled",
    toIsoTimestamp(now),
  );
}

/** The open offer and who it is for, or `null`. Visible to every member. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const offer = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (!offer || isLapsed(offer, new Date())) return null;
  return offer;
}

/**
 * Gate for offering and withdrawing: the owner role is required (the same
 * level as `org:manage_billing`), and the caller must be the recorded owner —
 * a second member holding the owner role is refused.
 */
async function assertRecordedOwner(actor: Actor, orgId: OrgId): Promise<void> {
  assertCan(actor, "org:manage_billing", orgResource(orgId));

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:manage_billing", {
      action: "org:manage_billing",
      resourceKind: "organization",
      allowed: false,
      reason: "denied_by_role",
    });
  }
}

/**
 * The open offer the caller may accept or decline. A lapsed offer is refused
 * as `expired` only for its offered member; anyone else sees `nothing_pending`.
 */
async function actionableOffer(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const offer = await ownershipHandoverRepo.findPendingHandover(orgId);
